import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec2, texture, fract, sin, dot, mix } from 'three/tsl';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, DoubleSide } = ctx.THREE;

  const root = new Group();
  root.userData.type = 'primary-cta';
  root.userData.handlers = {};

  const primitiveRefs = [];
  const tracked = {};

  const width = 3.5;
  const height = width * (320 / 512);
  const geometry = new PlaneGeometry(width, height);
  tracked.geometry = geometry;

  const fallbackMaterial = new MeshBasicNodeMaterial({
    color: 0x16161d,
    transparent: true,
    side: DoubleSide,
    depthWrite: false,
  });

  const plane = new Mesh(geometry, fallbackMaterial);
  root.add(plane);
  tracked.material = fallbackMaterial;

  const items = config.cinematicPrimitives ?? [];
  for (const p of items) {
    if (p && p.name && typeof ctx.primitives[p.name] === 'function') {
      const ref = ctx.primitives[p.name](root, p.params ?? {});
      primitiveRefs.push(ref);
    }
  }

  if (config.imageUrl) {
    ctx.textureLoader
      .loadTexture(config.imageUrl)
      .then((tex) => {
        if (!tex) return;
        tex.colorSpace = 'srgb';
        tracked.texture = tex;

        const uvs = uv();
        const base = texture(tex).sample(uvs);

        const noiseUV = uvs.mul(1024.0);
        const noise = fract(
          sin(dot(noiseUV, vec2(12.9898, 78.233))).mul(43758.5453)
        );
        const shaded = base.rgb.sub(base.rgb.mul(noise.mul(0.04)));
        const finalColor = mix(base.rgb, shaded, 0.5);

        const material = new MeshBasicNodeMaterial({
          colorNode: finalColor,
          transparent: true,
          side: DoubleSide,
          depthWrite: false,
        });

        plane.material = material;
        tracked.material = material;

        fallbackMaterial.dispose();
      })
      .catch(() => {});
  }

  root.userData.cleanup = () => {
    for (const ref of primitiveRefs) {
      if (ref && typeof ref.cleanup === 'function') {
        ref.cleanup();
      }
    }
    if (plane.material) {
      if (plane.material === tracked.material && tracked.texture) {
        tracked.texture.dispose();
      }
      plane.material.dispose();
    }
    if (tracked.geometry) {
      tracked.geometry.dispose();
    }
    if (root.parent) {
      root.parent.remove(root);
    }
  };

  return root;
}
